/** Exact lookup of an embedded asset by path (e.g. "/index.html", "/assets/index-abc.js"). */
export function getAsset(path: string): { body: Uint8Array; contentType: string } | null {
  const asset = assets.get(path);
  if (asset === undefined) return null;
  return { body: Uint8Array.from(atob(asset.content), (c) => c.charCodeAt(0)), contentType: asset.contentType };
}

/** Every embedded asset path. */
export function listAssetPaths(): string[] {
  return [...assets.keys()];
}
